    'Ligue o ChatGPT sem publicar o servidor nem abrir portas. O Nodus utiliza o túnel seguro oficial da OpenAI.',
  'Último paso: añade Nodus en ChatGPT': 'Último passo: adicione o Nodus ao ChatGPT',
  'Abre la configuración de ChatGPT, crea una app, elige «Tunnel» como conexión y selecciona el túnel que acabas de configurar.':
    'Abra as definições do ChatGPT, crie uma app, escolha «Tunnel» como ligação e selecione o túnel que acabou de configurar.',
  'Activa el modo desarrollador si es necesario': 'Ative o modo de programador se necessário',
  'En ChatGPT, ve a Configuración → Seguridad e inicio de sesión y activa Modo desarrollador. Si ya está activo, continúa con el siguiente paso.':
    'No ChatGPT, aceda a Definições → Segurança e início de sessão e ative o Modo de programador. Se já estiver ativo, avance para o passo seguinte.',
  'Abre el configurador de complementos': 'Abra o configurador de plugins',
  'En la configuración de ChatGPT, abre Complementos, pulsa Añadir complemento e introduce un nombre, por ejemplo «Nodus».':
    'Nas definições do ChatGPT, abra Plugins, selecione Adicionar plugin e introduza um nome, por exemplo «Nodus».',
  'Selecciona el túnel de Nodus': 'Selecione o túnel do Nodus',
  'Cuando ChatGPT solicite la conexión, elige Túnel y selecciona el túnel que acabas de configurar; no introduzcas la URL local.':
    'Quando o ChatGPT pedir a ligação, escolha Túnel e selecione o túnel que acabou de configurar; não introduza o URL local.',
  'Configura la autenticación': 'Configure a autenticação',
  'En Autenticación, selecciona Sin autenticación. No pegues aquí la clave de ejecución de OpenAI ni el token MCP local.':
    'Em Autenticação, selecione Sem autenticação. Não cole aqui a chave de execução da OpenAI nem o token MCP local.',
  'Confirma y termina': 'Confirme e conclua',
  'Marca Entiendo y quiero continuar y guarda el complemento. Nodus estará disponible en los chats donde actives el complemento.':
    'Selecione Compreendo e quero continuar e guarde o plugin. O Nodus ficará disponível nos chats em que ativar o plugin.',
  'Abrir configuración de ChatGPT': 'Abrir definições do ChatGPT',
  'Abrir diagnóstico': 'Abrir diagnóstico',
  'Desconectar': 'Desligar',
  'Crea un túnel en OpenAI': 'Crie um túnel na OpenAI',
  'Abre la página de túneles, pulsa Create y copia el identificador que empieza por tunnel_.':
    'Abra a página de túneis, clique em Create e copie o identificador que começa por tunnel_.',
  'Abrir túneles de OpenAI': 'Abrir túneis da OpenAI',
  'ID del túnel': 'ID do túnel',
  'Crea una clave de ejecución': 'Crie uma chave de execução',
  'La clave necesita permisos Tunnels Read + Use. Nodus la guarda en el almacén protegido de este dispositivo y nunca vuelve a mostrarla.':
    'A chave precisa das permissões Tunnels Read + Use. O Nodus guarda-a no armazenamento protegido deste dispositivo e nunca mais a apresenta.',
  'Crear clave de ejecución': 'Criar chave de execução',
  'Clave de ejecución': 'Chave de execução',
  'Ya hay una clave guardada; déjalo vacío para conservarla.': 'Já existe uma chave guardada; deixe em branco para a manter.',
  'Pega aquí la clave nueva': 'Cole aqui a nova chave',
  'Nodus activará MCP, descargará y verificará el cliente oficial y mantendrá la conexión mientras la aplicación esté abierta.':
    'O Nodus ativará o MCP, transferirá e verificará o cliente oficial e manterá a ligação enquanto a aplicação estiver aberta.',
  'Volver a conectar': 'Voltar a ligar',
  'Conectar con ChatGPT': 'Ligar ao ChatGPT',
  'Ver detalle técnico': 'Ver detalhes técnicos',
  'Cuando uses Nodus desde ChatGPT, OpenAI recibirá las consultas y los resultados que ChatGPT solicite. Las bóvedas permanecen en este equipo y el servidor local no se publica en Internet.':
    'Quando utilizar o Nodus a partir do ChatGPT, a OpenAI recebe os pedidos e resultados solicitados pelo ChatGPT. Os seus espaços permanecem neste dispositivo e o servidor local não é publicado na Internet.',
  'Borrar conexión guardada': 'Eliminar ligação guardada',
  'Claude Desktop puede conectar directamente con el servidor local de Nodus mediante este puente stdio:':
    'O Claude Desktop pode ligar-se diretamente ao servidor local do Nodus através desta ponte stdio:',
  'Copia esta configuración en Claude Desktop y reinicia la aplicación.': 'Copie esta configuração para o Claude Desktop e reinicie a aplicação.',
  'Usa Streamable HTTP con la URL local y la cabecera bearer siguientes.': 'Utilize Streamable HTTP com o seguinte URL local e cabeçalho bearer.',
  'El ID debe empezar por tunnel_ y contener los 32 caracteres que muestra OpenAI.': 'O ID deve começar por tunnel_ e conter os 32 caracteres apresentados pela OpenAI.',
  'Falta la clave de ejecución de OpenAI.': 'Falta a chave de execução da OpenAI.',
  'OpenAI todavía no ofrece el cliente de túnel para este sistema.': 'A OpenAI ainda não disponibiliza o cliente de túnel para este sistema.',
  'No se pudo descargar el cliente oficial. Comprueba la conexión a Internet e inténtalo de nuevo.': 'Não foi possível transferir o cliente oficial. Verifique a ligação à Internet e tente novamente.',
  'La descarga no superó la comprobación de seguridad y no se ha ejecutado.': 'A transferência falhou a verificação de segurança e não foi executada.',
  'OpenAI rechazó la clave. Crea una clave de ejecución nueva y vuelve a pegarla.': 'A OpenAI rejeitou a chave. Crie uma nova chave de execução e volte a colá-la.',
  'Tu cuenta necesita permisos Tunnels Read + Use en la organización de OpenAI.': 'A sua conta precisa das permissões Tunnels Read + Use na organização da OpenAI.',
  'OpenAI no encuentra ese túnel en la organización asociada a la clave.': 'A OpenAI não encontra esse túnel na organização associada à chave.',
  'No se puede alcanzar OpenAI. Revisa la conexión, el proxy o el cortafuegos.': 'Não é possível contactar a OpenAI. Verifique a ligação, o proxy ou a firewall.',
  'Nodus no pudo conectar el túnel con su servidor MCP local.': 'O Nodus não conseguiu ligar o túnel ao servidor MCP local.',
  'El cliente del túnel se detuvo. Pulsa Volver a conectar.': 'O cliente do túnel parou. Clique em Voltar a ligar.',
  'No se pudo completar la conexión. Abre el detalle técnico o inténtalo de nuevo.': 'Não foi possível concluir a ligação. Abra os detalhes técnicos ou tente novamente.',
