  'Exportar (.nodus)': 'Exportar (.nodus)',
  'Importar (.nodus)': 'Importar (.nodus)',
  'La copia incluye todos los datos de Nodus: textos extraídos, embeddings de ideas, resúmenes y pasajes, modelos seleccionados, grafo, ajustes y claves API, dentro de un archivo cifrado.':
    'A cópia de segurança inclui todos os dados do Nodus: textos extraídos, embeddings de ideias, resumos e passagens, modelos selecionados, grafo, definições e chaves API, num ficheiro encriptado.',
  'IA avanzada': 'IA avançada',
  'Modelo de extracción (extrae temas, ideas, evidencias y huecos)': 'Modelo de extração (extrai temas, ideias, evidências e lacunas)',
