  'Reindexar todos los embeddings': 'Reindexar todos os embeddings',
  'Se borrarán TODOS los embeddings existentes y se regenerarán desde cero. Esto consumirá tokens del proveedor de embeddings configurado. ¿Continuar?':
    'Serão eliminados TODOS os embeddings existentes e serão regenerados do zero. Isto irá consumir tokens do fornecedor de embeddings configurado. Continuar?',
  'Cargando…': 'A carregar…',
  'Cargar modelos': 'Carregar modelos',
  'OpenRouter acepta IDs como baai/bge-m3; si escribes BAAI:bge-m3 se normaliza automáticamente.':
    'O OpenRouter aceita IDs como baai/bge-m3; se escrever BAAI:bge-m3, é normalizado automaticamente.',
  'Reinicializar el grafo borrará TODAS las ideas, temas, conexiones, autores y huecos, y dejará cada obra sin analizar. Tu biblioteca de Zotero y tus ajustes se conservan. Esta acción no se puede deshacer.\n\n¿Continuar?':
    'Reinicializar o grafo irá eliminar TODAS as ideias, temas, ligações, autores e lacunas, e deixará cada obra por analisar. A sua biblioteca do Zotero e as suas definições são mantidas. Esta ação não pode ser anulada.\n\nContinuar?',
  'Grafo reinicializado. Vuelve a analizar tus obras para reconstruirlo.': 'Grafo reinicializado. Volte a analisar as suas obras para o reconstruir.',
  'Exportado': 'Exportado',
  'Introduce la contraseña de la copia.': 'Introduza a palavra-passe da cópia de segurança.',
