  'Fusionar todos los duplicados': 'Fundir todos os duplicados',
  'Se fusionarán {g} grupo(s), conservando en cada uno la copia marcada y reasignando sus ideas, evidencia y etiquetas. Las {n} copias sobrantes se eliminarán de la biblioteca de Nodus (Zotero no se modifica). ¿Continuar?':
    'Serão fundidos {g} grupo(s), mantendo em cada um a cópia marcada e reatribuindo as suas ideias, evidências e etiquetas. As {n} cópias excedentes serão eliminadas da biblioteca do Nodus (o Zotero não é alterado). Continuar?',
  'Duplicados': 'Duplicados',
