  '{n} evidencia(s)': '{n} evidência(s)',
  'Fusionar todas las ideas duplicadas': 'Fundir todas as ideias duplicadas',
  'Se hará primero una copia de seguridad completa de la base de datos. Después se fusionarán {g} grupo(s), conservando en cada uno la idea marcada y reasignándole toda la evidencia, ocurrencias, temas y conexiones del grafo de las {n} copias sobrantes, que se eliminarán. La evidencia no se pierde. ¿Continuar?':
    'Será feita primeiro uma cópia de segurança completa da base de dados. Depois serão fundidos {g} grupo(s), mantendo em cada um a ideia marcada e reatribuindo-lhe toda a evidência, ocorrências, temas e ligações do grafo das {n} cópias excedentes, que serão eliminadas. A evidência não se perde. Continuar?',
