  'Búsqueda semántica': 'Pesquisa semântica',
  'Texto citable': 'Texto citável',
  'Pulsa «Analizar» en la fila de una obra, o selecciona varias y analízalas juntas. Nodus lee el texto, extrae temas padre, ideas con evidencia y relaciones, y las añade al grafo. La columna Estado te dice en qué punto va cada obra.': 'Carrega em «Analisar» na linha de uma obra, ou seleciona várias e analisa-as em conjunto. O Nodus lê o texto, extrai temas principais, ideias com evidência e relações, e adiciona-as ao grafo. A coluna Estado diz-te em que ponto está cada obra.',
