  'personas': 'pessoas',
  'vínculos': 'vínculos',
  'lugares': 'lugares',
  'Cada persona reúne su parentesco, eventos, documentos y la evidencia que la respalda.':
    'Cada pessoa reúne o seu parentesco, eventos, documentos e a evidência que a sustenta.',
