  'Guardar vista actual': 'Guardar vista atual',
  'Actualizar vista': 'Atualizar vista',
  'Demo de bases de datos': 'Demo de bases de dados',
  'Tres tablas de investigación con todos los tipos de columna, relaciones, registros, análisis, una conversación y notas de ejemplo. Incluye un tutorial guiado.':
    'Três tabelas de investigação com todos os tipos de coluna, relações, registos, análises, uma conversa e notas de exemplo. Inclui um tutorial guiado.',
  'Cargar demo de bases de datos': 'Carregar demo de bases de dados',
  'Cargar datos de ejemplo': 'Carregar dados de exemplo',
  'Tutorial de bases de datos': 'Tutorial de bases de dados',
  'La lista de bases de datos, la tabla con columnas tipadas, la edición de celdas y las secciones de análisis y chat.':
    'A lista de bases de dados, a tabela com colunas tipadas, a edição de células e as secções de análise e chat.',
  'Se mostrará el tutorial de bases de datos.': 'O tutorial de bases de dados será mostrado.',
  'Bienvenido al modo bases de datos': 'Bem-vindo ao modo bases de dados',
  'Este es el modo bases de datos de Nodus: un gestor de tablas al estilo Notion, integrado en tu app. Te enseño en un minuto sus piezas con tres bases de datos de ejemplo ya cargadas. Puedes salir cuando quieras y volver a ver el tutorial desde Ajustes.':
    'Este é o modo bases de dados do Nodus: um gestor de tabelas ao estilo Notion, integrado na sua app. Num minuto mostro-lhe as suas partes com três bases de dados de exemplo já carregadas. Pode sair quando quiser e voltar a ver o tutorial a partir das Definições.',
  'Tus bases de datos': 'As suas bases de dados',
  'En la barra lateral aparecen todas tus bases de datos. Cada una tiene un identificador único autogenerado. Pulsa una para abrirla, o el botón + para crear una nueva. Aquí abajo están también las secciones de Análisis y Chat.':
    'Na barra lateral aparecem todas as suas bases de dados. Cada uma tem um identificador único gerado automaticamente. Clique numa para a abrir, ou no botão + para criar uma nova. Aqui em baixo estão também as secções de Análise e Chat.',
  'La tabla': 'A tabela',
  'Cada base de datos es una tabla de columnas tipadas: título, texto, número, fecha, hora, selección, selección múltiple y casilla. Arriba verás el número total de entradas y el porcentaje que suponen del total de todas tus bases de datos.':
    'Cada base de dados é uma tabela de colunas tipadas: título, texto, número, data, hora, seleção, seleção múltipla e caixa de verificação. Em cima verá o número total de entradas e a percentagem que representam do total de todas as suas bases de dados.',
  'Edita directamente': 'Edite diretamente',
  'Haz clic en cualquier celda para editarla al momento. Las columnas de selección muestran opciones con color que puedes añadir sobre la marcha; las casillas se marcan con un clic. Pasa el ratón por una fila para borrarla.':
    'Clique em qualquer célula para a editar de imediato. As colunas de seleção mostram opções com cor que pode adicionar na hora; as caixas marcam-se com um clique. Passe o rato por uma linha para a eliminar.',
  'Columnas a tu medida': 'Colunas à sua medida',
  'Pulsa la cabecera de una columna para renombrarla, cambiar su tipo o gestionar sus opciones, y usa el botón + del final de la cabecera para añadir nuevas columnas. Con «Nueva fila» añades registros.':
    'Clique no cabeçalho de uma coluna para a renomear, mudar o seu tipo ou gerir as suas opções, e use o botão + no final do cabeçalho para adicionar novas colunas. Com «Nova linha» adiciona registos.',
  'Análisis (próximamente)': 'Análise (brevemente)',
  'Aquí podrás elegir una base de datos y obtener estadísticas automáticas más un informe con IA, con gráficos y el cálculo a la vista para que sea reproducible. Llega en una próxima fase.':
    'Aqui poderá escolher uma base de dados e obter estatísticas automáticas mais um relatório com IA, com gráficos e o cálculo à vista para que seja reprodutível. Chega numa próxima fase.',
  'Chat de datos (próximamente)': 'Chat de dados (brevemente)',
  'Un chat adaptado para conversar con una o varias de tus bases de datos, capaz de generar gráficos y consultas reproducibles. También llega en una próxima fase.':
    'Um chat adaptado para conversar com uma ou várias das suas bases de dados, capaz de gerar gráficos e consultas reprodutíveis. Também chega numa próxima fase.',
  'Listo para tus datos': 'Pronto para os seus dados',
  'Esto es una demostración con datos de ejemplo. Cuando quieras empezar con los tuyos, crea una base de datos desde la barra lateral y añade tus columnas. Pronto podrás además importar CSV y subir archivos en masa.':
    'Isto é uma demonstração com dados de exemplo. Quando quiser começar com os seus, crie uma base de dados a partir da barra lateral e adicione as suas colunas. Em breve também poderá importar CSV e carregar ficheiros em massa.',
