  'Detalles y fuente': 'Detalhes e fonte',
  'Verificar ideas extraídas': 'Verificar ideias extraídas',
  'Cada idea aparece con su tipo (afirmación, hallazgo, constructo, método o marco), la obra de la que procede y la cita textual que la sostiene. Abre el detalle para comprobar si la lectura automática coincide con la tuya.':
    'Cada ideia aparece com o respetivo tipo (afirmação, achado, construto, método ou quadro), a obra de onde provém e a citação textual que a sustenta. Abrir o detalhe para verificar se a leitura automática coincide com a sua.',
  'Busca por palabras clave a través de ideas, obras, huecos, temas, autores y notas. Los resultados te llevan directamente al detalle correspondiente en cada vista.':
    'Procurar por palavras-chave em ideias, obras, lacunas, temas, autores e notas. Os resultados levam diretamente ao detalhe correspondente em cada vista.',
  'Tu espacio de notas': 'O seu espaço de notas',
  'Crea carpetas y notas en Markdown. Captura respuestas del asistente, borradores del taller de escritura, síntesis de debates e ideas individuales. Las citas internas (nodus://) permanecen clicables.':
    'Criar pastas e notas em Markdown. Capturar respostas do assistente, rascunhos da oficina de escrita, sínteses de debates e ideias individuais. As citações internas (nodus://) permanecem clicáveis.',
  'Debates: la estructura de una contradicción': 'Debates: a estrutura de uma contradição',
  'Cada relación de contradicción o refutación se despliega como un debate de dos bandos con sus autores, evidencias y cronología. Pides una síntesis al modelo para entender la tensión y decides cómo tu trabajo puede resolverla o aprovecharla.':
    'Cada relação de contradição ou refutação surge como um debate de dois lados, com os respetivos autores, evidências e cronologia. Pede-se ao modelo uma síntese para compreender a tensão e decide-se como o seu trabalho a pode resolver ou aproveitar.',
  'Mapa de cobertura: tu pregunta descompuesta': 'Mapa de cobertura: a sua pergunta decomposta',
  'Escribe tu pregunta de investigación y Nodus la desglosa en subpreguntas. Después mapea cuáles cubre tu corpus, cuáles parcialmente y cuáles quedan sin literatura. Es la herramienta para convertir una intuición vaga en un plan de búsqueda estructurado.':
    'Escrever a pergunta de investigação e o Nodus decompõe-a em subperguntas. De seguida, mapeia quais são cobertas pelo corpus, quais parcialmente e quais ficam sem literatura. É a ferramenta para transformar uma intuição vaga num plano de pesquisa estruturado.',
  'Notas: tu cuaderno de investigación': 'Notas: o seu caderno de investigação',
  'A lo largo del proceso habrás generado hallazgos en el asistente, borradores en el taller y síntesis de debates. Las Notas te permiten organizar todo ello en carpetas jerárquicas — piensa en capítulos y secciones — con un editor Markdown que conserva las citas clicables. Las ideas manuales que crees aquí se integran directamente en el grafo.':
    'Ao longo do processo, terá gerado achados no assistente, rascunhos na oficina e sínteses de debates. As Notas permitem organizar tudo isso em pastas hierárquicas — pense em capítulos e secções — com um editor Markdown que mantém as citações clicáveis. As ideias manuais criadas aqui integram-se diretamente no grafo.',
  'Inicio resume el estado de tu corpus, los análisis pendientes y el siguiente paso recomendado. La investigación es iterativa: escaneas más obras, vuelven a aparecer ideas y huecos, refinas la ruta y el borrador. Vuelve aquí entre vueltas. Puedes relanzar este recorrido desde Ajustes → Ayuda.':
    'O Início resume o estado do corpus, as análises pendentes e o próximo passo recomendado. A investigação é iterativa: analisam-se mais obras, voltam a surgir ideias e lacunas, refina-se o percurso e o rascunho. Voltar aqui entre rondas. Pode relançar este roteiro em Definições → Ajuda.',
