  "Aún no está implementado. Ayúdame a decidir cómo debería ser.": "Ainda não está implementado. Ajuda-me a decidir como deve ser.",
  "El hilo es público: describe los casos en abstracto, sin datos reales de alumnado.": "A discussão é pública: descreve os casos em abstrato, sem dados reais de alunos.",
  "Qué esperarías poder hacer en esta sección": "O que esperarias poder fazer nesta secção",
