  "Word, Excel, la plataforma del centro, papel… y qué te hace perder más tiempo.": "Word, Excel, a plataforma da escola, papel… e o que te faz perder mais tempo.",
  "Qué no debería hacer (opcional)": "O que não deveria fazer (opcional)",
