  "Tu contexto (opcional)": "O teu contexto (opcional)",
  "Ej.: Secundaria, Geografía e Historia, Andalucía": "Ex.: Secundário, Geografia e História, Andaluzia",
  "Se publicará en el hilo abierto de esta sección": "Será publicado na discussão aberta desta secção",
  "Hilo": "Discussão",
  "Podrás leer y responder a lo que hayan escrito otros docentes.": "Poderás ler e responder ao que outros docentes escreveram.",
  "Tu aportación está copiada y el hilo se ha abierto en el navegador. Pégala en el cuadro de comentario y publícala.": "O teu contributo está copiado e a discussão abriu no navegador. Cola-o na caixa de comentário e publica.",
  "No se pudo copiar automáticamente. Copia el texto de abajo y pégalo en el comentario del hilo.": "Não foi possível copiar automaticamente. Copia o texto abaixo e cola-o no comentário da discussão.",
  "Copiar de nuevo": "Copiar de novo",
  "Volver a abrir el hilo": "Voltar a abrir a discussão",
  "Llevar al hilo": "Ir para a discussão",
  "Gracias por echar una mano con el diseño.": "Obrigado por ajudares no desenho.",
  "Redactar y mantener la programación didáctica del curso, conectada con los materiales, las unidades y los criterios que ya usas para calificar.": "Redigir e manter a planificação didática do ano, ligada aos materiais, às unidades e aos critérios que já usas para avaliar.",
  "La pieza intermedia entre la programación anual y el día a día: temporalización, actividades, recursos y criterios que alimentan el cuaderno de notas.": "A peça entre a planificação anual e o dia a dia: calendarização, atividades, recursos e critérios que alimentam a pauta.",
  "Diseñar situaciones de aprendizaje completas: contexto, reto, producto final, secuencia de actividades y competencias implicadas.": "Desenhar situações de aprendizagem completas: contexto, desafio, produto final, sequência de atividades e competências envolvidas.",
  "Gestionar adaptaciones y medidas de atención a la diversidad por alumno o por grupo, con su seguimiento y su reflejo en la evaluación.": "Gerir adaptações e medidas de apoio por aluno ou por turma, com acompanhamento e reflexo na avaliação.",
  "Un cuaderno del docente: observaciones de clase, incidencias y seguimiento, con la opción de colgar cada nota de un curso, grupo o alumno.": "Um caderno do docente: observações de aula, ocorrências e acompanhamento, podendo ligar cada nota a um curso, turma ou aluno.",
  "Planificar y documentar proyectos de innovación educativa, desde la hipótesis inicial hasta la memoria final que pide la administración.": "Planear e documentar projetos de inovação educativa, da hipótese inicial ao relatório final exigido pela administração.",
  "Revisar copias": "Rever cópias de segurança",
  "Ocultar aviso": "Ocultar aviso",
  "Las copias de seguridad automáticas están desactivadas.": "As cópias de segurança automáticas estão desativadas.",
  "No se puede acceder a la carpeta de copias de seguridad.": "Não é possível aceder à pasta de cópias de segurança.",
