  "Limpieza automática de copias antiguas": "Limpeza automática de cópias antigas",
  "Usa el mismo día y hora que las copias automáticas. Si Nodus estaba cerrado, la limpieza pendiente se ejecuta al volver a abrirlo.": "Usa o mesmo dia e hora das cópias automáticas. Se o Nodus estava fechado, a limpeza pendente é executada quando voltar a abri-lo.",
  "Configura primero la carpeta de Recuperación y la contraseña maestra para poder verificar una copia superviviente.": "Configure primeiro a pasta de Recuperação e a palavra-passe mestra para poder verificar uma cópia sobrevivente.",
