  "{count} copia(s), {size}, supera(n) ahora la antigüedad configurada.": "{count} cópia(s), {size}, excede(m) atualmente a antiguidade configurada.",
  "Siempre se conservan al menos las tres copias normales más recientes. Las copias de otros equipos y los snapshots pre-update nunca entran en esta limpieza.": "São sempre conservadas pelo menos as três cópias normais mais recentes. As cópias de outros computadores e os snapshots pré-atualização nunca entram nesta limpeza.",
  "{count} copia(s) permanece(n) en la papelera de seguridad.": "{count} cópia(s) permanece(m) no lixo de segurança.",
  "{count} copia(s) ({size}) ya cumplió/cumplieron siete días en la papelera de seguridad y se eliminará(n) definitivamente en esta limpieza.": "{count} cópia(s) ({size}) já completou/completaram sete dias no lixo de segurança e será/serão eliminada(s) definitivamente nesta limpeza.",
  "Las copias seleccionadas se mueven primero a una papelera privada dentro de la carpeta de Recuperación. Solo se eliminan definitivamente después de siete días y tras verificar otra copia válida.": "As cópias selecionadas são primeiro movidas para um lixo privado dentro da pasta de Recuperação. Só são eliminadas definitivamente após sete dias e depois de verificar outra cópia válida.",
  "Al activar esta opción, el límite de antigüedad sustituye la rotación compacta anterior para las nuevas copias de este equipo.": "Ao ativar esta opção, o limite de antiguidade substitui a rotação compacta anterior nas novas cópias deste computador.",
  "Para cambiar la antigüedad, desactiva primero la limpieza y vuelve a activarla para confirmar el nuevo alcance.": "Para alterar a antiguidade, desative primeiro a limpeza e volte a ativá-la para confirmar o novo alcance.",
  "Limpiando…": "A limpar…",
  "Revisar y limpiar ahora": "Rever e limpar agora",
  "Última limpieza": "Última limpeza",
  "¿Activar la limpieza automática?": "Ativar a limpeza automática?",
  "Esta opción puede retirar copias antiguas automáticamente. Comprueba con atención la antigüedad seleccionada antes de continuar.": "Esta opção pode retirar cópias antigas automaticamente. Verifique cuidadosamente a antiguidade selecionada antes de continuar.",
  "Con la configuración actual, {count} copia(s) ({size}) pasaría(n) a la papelera de seguridad.": "Com a configuração atual, {count} cópia(s) ({size}) passaria(m) para o lixo de segurança.",
  "Las tres copias normales más recientes, las copias de otros equipos y los snapshots pre-update quedan protegidos.": "As três cópias normais mais recentes, as cópias de outros computadores e os snapshots pré-atualização ficam protegidos.",
  "Ninguna copia que se mueva en esta ejecución se eliminará definitivamente: permanecerá siete días en la papelera de seguridad.": "Nenhuma cópia movida nesta execução será eliminada definitivamente: permanecerá sete dias no lixo de segurança.",
  "Activar y ejecutar limpieza": "Ativar e executar a limpeza",
  "¿Revisar y limpiar copias antiguas?": "Rever e limpar cópias antigas?",
  "{count} copia(s) ({size}) cumple(n) ahora la regla de antigüedad.": "{count} cópia(s) ({size}) cumpre(m) atualmente a regra de antiguidade.",
  "Nodus volverá a calcular y verificar todo justo antes de mover archivos. Si algo no coincide, la operación se cancela sin borrar datos.": "O Nodus voltará a calcular e verificar tudo imediatamente antes de mover ficheiros. Se algo não coincidir, a operação é cancelada sem apagar dados.",
  "Las copias pasarán primero a la papelera de seguridad durante siete días.": "As cópias irão primeiro para o lixo de segurança durante sete dias.",
  "Ejecutar limpieza segura": "Executar limpeza segura",
  "{count} copia(s) se movió/movieron a la papelera de seguridad.": "{count} cópia(s) foi/foram movida(s) para o lixo de segurança.",
  "{count} copia(s) se eliminó/eliminaron definitivamente tras siete días.": "{count} cópia(s) foi/foram eliminada(s) definitivamente após sete dias.",
