  "Nodus Connector para Chrome": "Nodus Connector para Chrome",
  "Guarda la página o documento abierto en la Biblioteca de Nodus con metadatos, archivos, colección y etiquetas. Solo lee la pestaña cuando pulsas el icono.": "Guarda a página ou o documento aberto na Biblioteca Nodus com metadados, ficheiros, coleção e etiquetas. Só lê o separador quando clicas no ícone.",
