  "Esta página dejó de responder": "Esta página deixou de responder",
  "Ojo: si entras en tu navegador, la sesión se queda allí. Seguirás sin haber iniciado sesión en {host} dentro de Nodus, porque las cookies no se comparten entre navegadores.": "Atenção: se iniciar sessão no seu navegador, a sessão fica lá. Continuará sem sessão iniciada em {host} dentro do Nodus, porque os cookies não são partilhados entre navegadores.",
  "Ojo: si entras en tu navegador, la sesión se queda allí. Seguirás sin haber iniciado sesión en Google dentro de Nodus, porque las cookies no se comparten entre navegadores.": "Atenção: se iniciar sessão no seu navegador, a sessão fica lá. Continuará sem sessão iniciada no Google dentro do Nodus, porque os cookies não são partilhados entre navegadores.",
  "Si {host} admite entrar con contraseña o con un enlace por correo, esa vía sí funciona aquí dentro, y Nodus recordará la sesión.": "Se {host} aceitar palavra-passe ou uma ligação por e-mail, essa via funciona aqui dentro, e o Nodus recordará a sessão.",
  "Volver e intentar con contraseña": "Voltar e tentar com palavra-passe",
  "Usar {host} en mi navegador": "Usar {host} no meu navegador",
  "Para que Nodus lea tu Gmail o tu Drive haría falta otra cosa: conectar la cuenta desde Ajustes, que es la vía que Google sí admite para aplicaciones de escritorio. Todavía no está disponible.": "Para o Nodus ler o seu Gmail ou Drive seria preciso outra coisa: ligar a conta nas Definições, a via que o Google permite a aplicações de secretária. Ainda não está disponível.",
  "No es un fallo de Nodus: Google rechaza el inicio de sesión desde cualquier navegador incrustado en otra aplicación.": "Não é uma falha do Nodus: o Google recusa o início de sessão a partir de qualquer navegador incorporado noutra aplicação.",
  "Google no permite iniciar sesión desde un navegador integrado": "O Google não permite iniciar sessão a partir de um navegador integrado",
