  "Chromium borra las cookies por dominio registrable: al borrar las de un subdominio se borran también las del dominio principal y sus demás subdominios.": "O Chromium apaga as cookies por domínio registável: apagar as de um subdomínio apaga também as do domínio principal e dos restantes subdomínios.",
  "Nodus puede medir la caché y el tamaño total del perfil. Chromium no informa del tamaño de cada categoría de almacenamiento por separado, así que las demás se muestran por número de sitios afectados.": "O Nodus pode medir a cache e o tamanho total do perfil. O Chromium não indica o tamanho de cada categoria de armazenamento em separado, por isso as restantes são mostradas pelo número de sites afetados.",
  "Nodus Browser conserva cookies y almacenamiento de sitio para que sigas con la sesión iniciada donde corresponda. Nodus no guarda usuarios ni contraseñas, y no incluye gestor de contraseñas.": "O Nodus Browser conserva cookies e armazenamento de site para que continue com a sessão iniciada onde for adequado. O Nodus não guarda utilizadores nem palavras-passe e não inclui gestor de palavras-passe.",
